import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../../../styles/GlobalStyles.css';

const OrganizerDashboard = () => {
  // State variables to hold the events, loading status, and error messages.
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // This function fetches events for the organizer from the backend.
  const fetchEvents = async () => {
    try {
      setLoading(true);
      // Retrieve the token (assumed stored in localStorage)
      const token = localStorage.getItem('token');
      // Make a GET request to the organizer events endpoint
      const response = await axios.get('http://localhost:5000/api/organizer/my-events', {
        headers: { Authorization: `Bearer ${token}` }
      });
      // Update state with fetched events
      setEvents(response.data.events);
      setLoading(false);
      setError(null);
    } catch (err) {
      setError('Failed to fetch events');
      setLoading(false);
    }
  };

  // useEffect to fetch data on component mount and to set up polling every 30 seconds.
  useEffect(() => {
    fetchEvents();
    const intervalId = setInterval(fetchEvents, 30000); // Poll every 30,000 milliseconds
    return () => clearInterval(intervalId); // Cleanup when component unmounts
  }, []);

  return (
    <div className="container">
      <div className="card">
        <h2>Organizer Dashboard</h2>
        <p>Manage your events, view ticket sales, and track performance.</p>
        
        {/* Event Management Section */}
        <section>
          <h3>Event Management</h3>
          <button className="btn" style={{ marginRight: '1rem' }}>Create New Event</button>
          <button className="btn">Manage Events</button>
          <div style={{ marginTop: '1rem' }}>
            <h4>Your Events</h4>
            {loading ? (
              <p>Loading events...</p>
            ) : error ? (
              <p style={{ color: 'red' }}>{error}</p>
            ) : events.length > 0 ? (
              <ul>
                {events.map(event => (
                  <li key={event._id} style={{ marginBottom: '0.5rem' }}>
                    <strong>{event.title}</strong> | Date: {new Date(event.date).toLocaleDateString()}<br />
                    Registrations: {event.registrations || 0} | Revenue: ₹{event.ticketSales || 0}
                  </li>
                ))}
              </ul>
            ) : (
              <p>No events found.</p>
            )}
          </div>
        </section>
        
        {/* Analytics & Insights Section */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Analytics & Insights</h3>
          <p>Total Events: {events.length}</p>
          <p>
            Total Registrations:{' '}
            {events.reduce((acc, event) => acc + (event.registrations || 0), 0)}
          </p>
          <p>
            Total Revenue: ₹
            {events.reduce((acc, event) => acc + (event.ticketSales || 0), 0)}
          </p>
        </section>
        
        {/* Notifications & Updates Section */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Notifications & Updates</h3>
          <button className="btn">Send Update to Attendees</button>
        </section>
      </div>
    </div>
  );
};

export default OrganizerDashboard;
